'use strict';
// Read-only readiness probe of currently published 213; does not deploy 214.
const assert=require('node:assert/strict'),fs=require('node:fs'),cp=require('node:child_process'),crypto=require('node:crypto');
const {request,chromium,webkit}=require('playwright');
const ROOT=process.env.PWA_ROOT||process.cwd(),OUT=process.env.PWA_OUTPUT||'artifacts/release214-update',PIN='7294be99639c31db2e887c634c71578975c985f8',BASE='https://wataruyamashita-collab.github.io/boki-rpg-app/';
const git=f=>cp.execFileSync('git',['show',PIN+':'+f],{cwd:ROOT,maxBuffer:32*1024*1024}),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const manifest=JSON.parse(git('pwa-release-manifest.json')),files=[...new Set([...Object.keys(manifest.assets),...Object.keys(manifest.pages||{}),'index.html','form-a.html','service-worker.js','manifest.webmanifest','icons/app-icon.svg','pwa-release-manifest.json'])];
const report={status:'RUNNING',purpose:'Verify authorized Actions real-URL access before any deployment',pin:PIN,release:manifest.release,base:BASE,assets:[],browsers:[]};fs.mkdirSync(OUT,{recursive:true});const save=()=>fs.writeFileSync(OUT+'/live-readiness.json',JSON.stringify(report,null,2));
(async()=>{try{const api=await request.newContext();try{assert.equal(files.length,26);for(const file of files){const response=await api.get(new URL(file,BASE).href+'?predeploy='+PIN,{headers:{'Cache-Control':'no-cache'}});assert.equal(response.status(),200);assert.equal(hash(await response.body()),hash(git(file)));report.assets.push({file,status:200,sha256:hash(git(file))});}}finally{await api.dispose();}
 for(const [engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch(),context=await browser.newContext({serviceWorkers:'allow'});try{const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto(BASE);await page.waitForFunction(()=>window.App?.controller&&navigator.serviceWorker.controller);const proof=await page.evaluate(async()=>({scope:(await navigator.serviceWorker.getRegistration()).scope,worker:await App.storageClients(navigator.serviceWorker.controller),release:document.querySelector('script[src*="js/app.js"]').src}));assert.equal(proof.scope,BASE);assert.equal(proof.worker.release,manifest.release);assert.deepEqual(errors,[]);report.browsers.push({engine,version:browser.version(),status:'PASS',proof,errors});}finally{await context.close();await browser.close();}}
 report.status='PASS';}catch(e){report.status='FAIL';report.error=e.stack;process.exitCode=1;}finally{save();console.log('LIVE_READINESS '+JSON.stringify(report));}})();
